window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7e8848f9ab56fcf8"]={"versions": [{"id": "FIG-7e8848f9ab56fcf8", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Architektur-Übersicht zur Spezifikation von VFB Timing Blueprints im Kontext des AUTOSAR Standardization Templates (TPS StandardizationTemplate) und der AUTOSAR Timing Extensions. Das Schaubild veranschaulicht die Referenzbeziehungen zwischen abstrakten Timing-Vorgaben innerhalb eines <code>VFB Timing Blueprint</code> und den zugehörigen Blueprint-Elementen eines Software-Komponenten-Ports (<code>Blueprint</code> mit <code>Port Prototype Blueprint</code> und <code>Port Interface</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche sowie eine Legende:</p>\n<ul class=\"fig-list\"><li><strong>VFB Timing Blueprint</strong> (hellblau hinterlegter Container):\n<ul class=\"fig-list\"><li><code>TC &lt;Type&gt;</code>: Timing Constraint (gestrichelter Kasten mit Schatten), repräsentiert eine Timing-Bedingung/Schranke eines bestimmten Typs (z. B. Age Constraint <code>AC</code>).\n</li><li><code>TDE &lt;Type&gt;</code>: Timing Description Event (gestrichelter Kasten mit Schatten), repräsentiert ein Timing-Ereignis bezogen auf den Virtual Function Bus (VFB).\n</li></ul>\n</li><li><strong>Blueprint</strong> (Container für Entwurfselemente):\n<ul class=\"fig-list\"><li><code>Port Prototype Blueprint</code>: Gestricheltes Port-Symbol (Quadrat mit nach rechts gerichtetem gefülltem Dreieckspfeil), modelliert die Vorlage für einen Schnittstellen-Port.\n</li><li><code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Schnittstellenbeschreibung mit Typ und referenziertem Schnittstellenelement (z. B. Variable Data Prototype, Client-Server-Operation, Mode Declaration, Trigger).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Referenzen</strong>:\n<ul class=\"fig-list\"><li>Gerichteter Pfeil von <code>TC &lt;Type&gt;</code> auf <code>TDE &lt;Type&gt;</code>: Das Timing Constraint bindet oder referenziert das Timing Description Event.\n</li><li>Gerichteter Pfeil von <code>TDE &lt;Type&gt;</code> auf das Port-Symbol von <code>Port Prototype Blueprint</code>: Das VFB-Timing-Ereignis (spezifiziert als <code>TDEventVfbPort</code>) referenziert den Port-Prototyp-Blueprint.\n</li><li>Abgewinkelter gerichteter Pfeil von <code>TDE &lt;Type&gt;</code> auf <code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Das Timing-Ereignis referenziert das spezifische Element der Port-Schnittstelle.\n</li><li>Gerichteter Pfeil von <code>Port Prototype Blueprint</code> auf <code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Der Port-Blueprint typisiert sich über das zugehörige Port Interface.\n</li></ul>\n</li><li><strong>Legend</strong>:\n<ul class=\"fig-list\"><li><code>TDE</code>: Timing Description Event\n</li><li><code>TDEC</code>: Timing Description Event Chain\n</li><li><code>TC</code>: Timing Constraint\n</li><li><code>VDPR</code>: Variable Data Prototype Received\n</li><li><code>VDPS</code>: Variable Data Prototype Sent\n</li><li><code>S/R</code>: Sender/Receiver\n</li><li><code>PET</code>: Periodic Event Triggering\n</li><li><code>AC</code>: Age Constraint\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Modellierungs- und Referenzierungsmuster für Timing-Spezifikationen auf Blueprint-Ebene. Ein VFB-Timing-Ereignis (<code>TDE</code>) dient als Ankerpunkt für Timing-Constraints (<code>TC</code>), beispielsweise zur Begrenzung von Latenzen oder Datenfrische. Das <code>TDE</code> referenziert einerseits den logischen Port (<code>Port Prototype Blueprint</code>) und andererseits das feingranulare Schnittstellenelement (<code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>), an dem das Ereignis (Senden, Empfangen oder Triggern) semantisch auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>In einem <code>VFB Timing Blueprint</code> muss <code>TDEventVfbPort</code> zwingend auf einen <code>PortPrototypeBlueprint</code> referenzieren (<code>[constr_2589]</code>).\n</li><li>Bei der Ableitung einer konkreten VFB-Timing-Beschreibung (<code>VfbTiming</code>) aus dem Blueprint muss die Referenz zu <code>PortPrototypeBlueprint</code> durch die entsprechende Referenz auf den tatsächlichen <code>PortPrototype</code> ersetzt werden.\n</li><li>Die im Blueprint optional freibleibende Software-Komponenten-Referenz (<code>VfbTiming.component</code>) ist in der abgeleiteten Implementierung zwingend auf die konkrete Software-Komponente zu setzen.\n</li></ul>"}, {"id": "FIG-fded0df0890cda0e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Architektur-Übersicht zur Spezifikation von VFB Timing Blueprints im Kontext des AUTOSAR Standardization Templates (TPS StandardizationTemplate) und der AUTOSAR Timing Extensions. Das Schaubild veranschaulicht die Referenzbeziehungen zwischen abstrakten Timing-Vorgaben innerhalb eines <code>VFB Timing Blueprint</code> und den zugehörigen Blueprint-Elementen eines Software-Komponenten-Ports (<code>Blueprint</code> mit <code>Port Prototype Blueprint</code> und <code>Port Interface</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche sowie eine Legende:</p>\n<ul class=\"fig-list\"><li><strong>VFB Timing Blueprint</strong> (hellblau hinterlegter Container):\n<ul class=\"fig-list\"><li><code>TC &lt;Type&gt;</code>: Timing Constraint (gestrichelter Kasten mit Schatten), repräsentiert eine Timing-Bedingung/Schranke eines bestimmten Typs (z. B. Age Constraint <code>AC</code>).\n</li><li><code>TDE &lt;Type&gt;</code>: Timing Description Event (gestrichelter Kasten mit Schatten), repräsentiert ein Timing-Ereignis bezogen auf den Virtual Function Bus (VFB).\n</li></ul>\n</li><li><strong>Blueprint</strong> (Container für Entwurfselemente):\n<ul class=\"fig-list\"><li><code>Port Prototype Blueprint</code>: Gestricheltes Port-Symbol (Quadrat mit nach rechts gerichtetem gefülltem Dreieckspfeil), modelliert die Vorlage für einen Schnittstellen-Port.\n</li><li><code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Schnittstellenbeschreibung mit Typ und referenziertem Schnittstellenelement (z. B. Variable Data Prototype, Client-Server-Operation, Mode Declaration, Trigger).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Referenzen</strong>:\n<ul class=\"fig-list\"><li>Gerichteter Pfeil von <code>TC &lt;Type&gt;</code> auf <code>TDE &lt;Type&gt;</code>: Das Timing Constraint bindet oder referenziert das Timing Description Event.\n</li><li>Gerichteter Pfeil von <code>TDE &lt;Type&gt;</code> auf das Port-Symbol von <code>Port Prototype Blueprint</code>: Das VFB-Timing-Ereignis (spezifiziert als <code>TDEventVfbPort</code>) referenziert den Port-Prototyp-Blueprint.\n</li><li>Abgewinkelter gerichteter Pfeil von <code>TDE &lt;Type&gt;</code> auf <code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Das Timing-Ereignis referenziert das spezifische Element der Port-Schnittstelle.\n</li><li>Gerichteter Pfeil von <code>Port Prototype Blueprint</code> auf <code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>: Der Port-Blueprint typisiert sich über das zugehörige Port Interface.\n</li></ul>\n</li><li><strong>Legend</strong>:\n<ul class=\"fig-list\"><li><code>TDE</code>: Timing Description Event\n</li><li><code>TDEC</code>: Timing Description Event Chain\n</li><li><code>TC</code>: Timing Constraint\n</li><li><code>VDPR</code>: Variable Data Prototype Received\n</li><li><code>VDPS</code>: Variable Data Prototype Sent\n</li><li><code>S/R</code>: Sender/Receiver\n</li><li><code>PET</code>: Periodic Event Triggering\n</li><li><code>AC</code>: Age Constraint\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Modellierungs- und Referenzierungsmuster für Timing-Spezifikationen auf Blueprint-Ebene. Ein VFB-Timing-Ereignis (<code>TDE</code>) dient als Ankerpunkt für Timing-Constraints (<code>TC</code>), beispielsweise zur Begrenzung von Latenzen oder Datenfrische. Das <code>TDE</code> referenziert einerseits den logischen Port (<code>Port Prototype Blueprint</code>) und andererseits das feingranulare Schnittstellenelement (<code>Port Interface &lt;Type&gt; &lt;Element&gt;</code>), an dem das Ereignis (Senden, Empfangen oder Triggern) semantisch auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>In einem <code>VFB Timing Blueprint</code> muss <code>TDEventVfbPort</code> zwingend auf einen <code>PortPrototypeBlueprint</code> referenzieren (<code>[constr_2589]</code>).\n</li><li>Bei der Ableitung einer konkreten VFB-Timing-Beschreibung (<code>VfbTiming</code>) aus dem Blueprint muss die Referenz zu <code>PortPrototypeBlueprint</code> durch die entsprechende Referenz auf den tatsächlichen <code>PortPrototype</code> ersetzt werden.\n</li><li>Die im Blueprint optional freibleibende Software-Komponenten-Referenz (<code>VfbTiming.component</code>) ist in der abgeleiteten Implementierung zwingend auf die konkrete Software-Komponente zu setzen.\n</li></ul>"}], "trans": [{"from": "FIG-7e8848f9ab56fcf8", "to": "FIG-fded0df0890cda0e", "fr": "R4.2.2", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
